effect.shader:
float beHashV(vec2 p, float t) { return fract(sin(dot(p + t, vec2(12.9898, 78.233))) * 43758.5453); }
void main() {
vec2 uv = acScreenNorm;
vec2 px = vec2(1.0) / max(acScreenSize, vec2(1.0));
float t = acTime * max(speed, 0.0);
float band = smoothstep(0.02, 0.0, abs(fract(uv.y * 3.0 + t * 0.05) - 0.5) - 0.44) * lines;
vec2 wob = vec2((beHashV(vec2(floor(uv.y * 90.0), 1.0), floor(t * 8.0)) - 0.5) * band * 8.0 * px.x, 0.0);
vec2 fr = vec2(fringe * px.x, 0.0);
float r = texture2DCv(inputImg.texture, clamp(uv + wob - fr, vec2(0.0), vec2(1.0))).r;
float g = texture2DCv(inputImg.texture, clamp(uv + wob, vec2(0.0), vec2(1.0))).g;
float b = texture2DCv(inputImg.texture, clamp(uv + wob + fr, vec2(0.0), vec2(1.0))).b;
float n = beHashV(floor(uv * vec2(480.0, 270.0)), floor(t * 24.0)) - 0.5) * noise;
vec4 src = texture2DCv(inputImg.texture, uv);
gl_FragColor = vec4(clamp(vec3(r, g, b) + n, vec3(0.0), vec3(1.0)), src.a);
}
